window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["distributed-training"]={"title":"分布式训练：沿数据、张量、流水线和状态四个轴拆分","subtitle":"从全局批量与 all-reduce，到张量并行、pipeline bubble、ZeRO/FSDP、3D 并行和故障检查点。","thesis":"分布式训练不是“多加 GPU”，而是决定参数、梯度、优化器状态、激活和样本分别放在哪里、何时通信。扩展效率受<b>计算/通信比、峰值内存、全局批量语义、拓扑和故障恢复</b>共同限制。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"每卡 4 样本、累积 8 步，8 GPU","rule":"每卡 4×累积8×8卡=256 样本","steps":"800/(8×140)=71.4%","interpretation":"额外 40ms 来自通信、同步和负载不均"}}],"formulas":[{"id":"distributed-training-global-batch-gradient","section":2,"formulaIndex":1,"symbols":[{"name":"B","meaning":"一次参数更新实际使用的全局样本数量","evidence":"B全局 是一次参数更新实际使用的样本数"},{"name":"b","meaning":"每个数据并行设备在一个微步处理的局部批量","evidence":"b 是每卡每个微步的局部 batch"},{"name":"n","meaning":"并行处理不同样本的数据并行副本数","evidence":"n 是数据并行副本数"},{"name":"a","meaning":"执行一次参数更新前累计的微步数量","evidence":"a 是累计多少个微步才更新"},{"name":"g","meaning":"本地或全局平均的参数梯度","evidence":"gᵣ 是第 r 个 rank 的累计梯度"},{"name":"r","meaning":"参与数据并行训练的进程或设备编号","evidence":"r 是 rank 编号"}]},{"id":"distributed-training-pipeline-bubble","section":5,"formulaIndex":1,"symbols":[{"name":"f","meaning":"理想化流水线中没有有效计算的时间比例","evidence":"f气泡 是理想化空闲时间比例"},{"name":"p","meaning":"流水线划分出的连续模型阶段数量","evidence":"p 是流水线阶段数"},{"name":"m","meaning":"一个批次拆出的 micro-batch 数量","evidence":"m 是一个批次拆出的 micro-batch 数"}]},{"id":"distributed-training-3d-global-batch","section":7,"formulaIndex":1,"symbols":[{"name":"B","meaning":"全局批量或每个数据副本的局部微批量","evidence":"B微批 是每个数据并行副本一次处理的样本数"},{"name":"a","meaning":"累积多少个局部微批后执行一次参数更新","evidence":"a 是梯度累积步数"},{"name":"N","meaning":"处理不同样本的数据并行副本数量","evidence":"N数据并行 是处理不同样本的数据副本数"},{"name":"TP","meaning":"共同计算同一层张量的张量并行度","evidence":"TP 与 PP 只是共同完成同一副本的模型计算"},{"name":"PP","meaning":"共同计算同一样本不同模型阶段的流水线并行度","evidence":"TP 与 PP 只是共同完成同一副本的模型计算"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"分布式训练先核算权重、梯度、优化器、激活和缓冲，再选择如何分片。","evidence":"权重、梯度、优化器、激活、通信缓冲和碎片逐项估算"},"problem":{"answer":"它解决推理权重虽可装入单卡，但完整反向训练状态远超单卡内存的问题。","evidence":"为何 24GB GPU 仍不能全量 Adam 微调"},"inputOutput":{"answer":"输入是模型、精度、优化器、batch 与序列配置，输出是峰值内存账和并行选择。","evidence":"输出是各类状态的峰值及每卡能否容纳"},"mechanism":{"answer":"数据、状态、单层、模型层和激活分别可由不同并行或重计算策略处理。","evidence":"分片策略分别解决不同对象"},"interpretation":{"answer":"权重能加载只证明推理主体可放下，不证明梯度与状态也能运行。","evidence":"不证明反向传播能运行"},"boundary":{"answer":"静态估算受实现、碎片和通信缓冲影响，必须实测峰值并保留余量。","evidence":"必须用实测峰值留出安全余量"}},{"section":2,"definition":{"answer":"同步数据并行让各副本看不同样本，再归约梯度执行同一次参数更新。","evidence":"各 rank 用相同全局平均梯度更新"},"problem":{"answer":"它在扩大样本吞吐时保持所有模型副本参数一致。","evidence":"为什么最后参数仍保持一致"},"inputOutput":{"answer":"输入是各 rank 本地累计梯度，输出是每个副本相同的全局平均梯度。","evidence":"把结果发回每一方"},"mechanism":{"answer":"all-reduce 对各设备梯度求和或平均，所有副本再使用同一结果更新。","evidence":"共同求和并把结果发回每一方"},"interpretation":{"answer":"设备数变化会改变全局批量和优化噪声，需固定训练语义后再比较硬件。","evidence":"会增大全局批量，改变梯度噪声"},"boundary":{"answer":"数据顺序、随机流、dropout 与浮点归约顺序仍会令训练轨迹不同。","evidence":"loss 看似相同不代表实验相同"}},{"section":3,"definition":{"answer":"运行例同时计算八卡数据并行的全局批量与固定工作强扩展效率。","evidence":"8 卡全局批量与强扩展效率"},"problem":{"answer":"它检验设备、局部 batch 和累积怎样决定一次更新样本数及速度损耗。","evidence":"一次优化步看了多少样本"},"inputOutput":{"answer":"输入是八卡、每卡四样本、累积八步和实测时间，输出批量与效率。","evidence":"每卡 4 样本、累积 8 步，8 GPU"},"mechanism":{"answer":"八个副本各累计八个微步，第八步同步后才共同更新一次。","evidence":"第 8 步同步后才进行一次全局更新"},"interpretation":{"answer":"百分之七十一点四效率表明理想加速被通信、同步和负载不均削弱。","evidence":"额外 40ms 来自通信、同步和负载不均"},"boundary":{"answer":"该效率只适用于固定总工作的强扩展，不能直接代表弱扩展或最终质量。","evidence":"同一总工作时间"}},{"section":4,"definition":{"answer":"张量并行把同一层矩阵或注意力头分给多卡共同完成。","evidence":"把同一层矩阵或注意力头分给多张卡共同计算"},"problem":{"answer":"它使单层权重或激活超过单卡容量时仍能执行该层计算。","evidence":"单个 4096×16384 MLP 放不下一张卡"},"inputOutput":{"answer":"输入是同一批激活和分片权重，输出是经集合通信拼回的等价层结果。","evidence":"输出要经过集合通信拼回"},"mechanism":{"answer":"列并行产生局部输出，行并行消费局部特征并用 all-reduce 汇总。","evidence":"后续行并行可消费局部特征"},"interpretation":{"answer":"每卡内存下降但单位卡吞吐下降，通常表示通信或小算子抵消收益。","evidence":"通信或局部算子太小抵消了收益"},"boundary":{"answer":"层内通信频繁，TP 更适合同节点高速互连，不宜跨慢网盲目增加度数。","evidence":"不应仅为“多用几张卡”跨慢网络扩大"}},{"section":5,"definition":{"answer":"流水线并行把连续模型层分成阶段，并以多个微批填充前向反向节拍。","evidence":"把连续模型层分成 p 个阶段"},"problem":{"answer":"它让模型层跨设备放置，同时尽量减少阶段等待形成的气泡。","evidence":"理想气泡比例是多少"},"inputOutput":{"answer":"输入是阶段数、微批数和各阶段成本，输出是调度、气泡率和峰值激活。","evidence":"一个大 batch 再拆成 m 个 micro-batch"},"mechanism":{"answer":"微批依次穿过阶段，增加微批可填充启动收尾空闲但会增加其他开销。","evidence":"增加 m 减气泡"},"interpretation":{"answer":"四阶段八微批的简化气泡约百分之二十七点三，表示仍有等待时间。","evidence":"气泡约 27.3%"},"boundary":{"answer":"简式假设阶段成本接近，不含通信、前后向差异和异步权重版本问题。","evidence":"只描述阶段成本相近的简化调度"}},{"section":6,"definition":{"answer":"ZeRO 和 FSDP 在数据并行副本间分片优化器、梯度及参数等冗余状态。","evidence":"不再各自长期保存完整训练状态"},"problem":{"answer":"它降低普通数据并行每卡复制完整 Adam 状态和参数的内存浪费。","evidence":"怎样按 rank 分摊"},"inputOutput":{"answer":"输入是按 rank 分片的训练状态，输出仍应等价于同步数据并行的一次更新。","evidence":"输出仍应等价于一次同步数据并行更新"},"mechanism":{"answer":"计算前 all-gather 本层参数，反向后 reduce-scatter 梯度并保留各自分片。","evidence":"只把不同分片留在各卡"},"interpretation":{"answer":"峰值下降而集合通信上升是用通信换内存的预期结果。","evidence":"用通信换内存的预期结果"},"boundary":{"answer":"细粒度预取、offload 和检查点重分片会引入带宽、复杂度与恢复限制。","evidence":"可能被搬运带宽限制"}},{"section":7,"definition":{"answer":"三维并行按设备拓扑组合数据、张量和流水线三个协作轴。","evidence":"DP、TP、PP 分别表示数据并行、张量并行和流水线并行"},"problem":{"answer":"它在大集群中匹配不同通信频率与链路速度，并保持 batch 语义正确。","evidence":"通信域如何不同"},"inputOutput":{"answer":"输入是拓扑、并行度与批量配置，输出是 rank 分组、通信域和优化语义。","evidence":"输出是 rank 分组、通信域与不变的优化器语义"},"mechanism":{"answer":"TP 放高速域、PP 传相邻激活、DP 同步不同样本的梯度与状态。","evidence":"TP 组内每层频繁通信"},"interpretation":{"answer":"只有 DP 副本处理不同样本，TP 和 PP 合作同一样本所以不增加全局批量。","evidence":"TP/PP 合作处理同一批样本"},"boundary":{"answer":"把全部 GPU 都乘入 batch 会错误放大全局批量并改变学习率和训练轨迹。","evidence":"错误改变学习率和训练轨迹"}},{"section":8,"definition":{"answer":"可靠检查点保存恢复训练所需的模型、优化器、随机流、数据游标和并行元数据。","evidence":"保存模型、优化器、调度器、随机数、数据游标"},"problem":{"answer":"它避免长时间训练因节点故障从头开始或从不一致状态继续。","evidence":"训练两周后一个节点故障"},"inputOutput":{"answer":"输入是全量分片训练状态，输出是原子、完整且可重分片或明确受限的快照。","evidence":"临时产物+原子清单"},"mechanism":{"answer":"各 rank 写分片并由原子清单提交，恢复时重建状态、随机流和数据位置。","evidence":"避免一半 rank 成功的损坏快照"},"interpretation":{"answer":"真实恢复后损失和样本序列一致，比只检查文件存在更能证明正确。","evidence":"比较恢复后 loss/样本序列"},"boundary":{"answer":"间隔需权衡写入开销和丢失计算，成员变化还会影响 batch 与随机流。","evidence":"在写入开销与丢失计算间取舍"}},{"section":9,"definition":{"answer":"强扩展固定总工作测加速，弱扩展固定每卡工作测规模增长下的单位效率。","evidence":"强扩展固定总模型与总工作"},"problem":{"answer":"它避免 GPU 增加后用不同问题规模或不同训练语义制造虚假加速。","evidence":"应该保持总问题大小还是每卡问题大小"},"inputOutput":{"answer":"输入是多设备数下同一协议，输出速度、效率、资源、恢复和质量联合报告。","evidence":"输出是速度、效率、内存、功耗、恢复与最终质量的联合报告"},"mechanism":{"answer":"trace 把 step 拆成数据、前向、反向、通信、优化器与检查点定位等待。","evidence":"GPU 利用率低只是症状"},"interpretation":{"answer":"MFU 低只说明有效模型计算占峰值较少，不能单独定位具体瓶颈。","evidence":"不能单独判断瓶颈来自数据、通信还是小算子"},"boundary":{"answer":"吞吐提升但最终质量下降不算成功，必须同时验证 batch、随机和数值语义。","evidence":"吞吐提高但最终质量下降不是成功扩展"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>计算训练内存与全局批量；区分 DP/TP/PP/ZeRO；手算流水线气泡和扩展效率；设计数值一致与恢复门禁。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>权重能放下，不代表训练能放下<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">一个 7B FP16 模型约 14GB，为何 24GB GPU 仍不能全量 Adam 微调？</p><p><code>7B</code> 表示约 70 亿个参数，FP16 每个权重通常占 2 bytes，所以只存推理权重约需 14GB。全量训练还需要更高精度主权重、每个参数的梯度，以及 Adam 为每个参数维护的两组历史统计；“激活”则是前向各层为反向传播暂存的中间结果。混合精度粗略每参数可能需要 12–20 bytes 状态，7B 远超单卡；长序列激活也可主导。</p><p>内存账的输入是参数量、数值精度、优化器、batch、序列长度和临时缓冲，输出是各类状态的峰值及每卡能否容纳。分片策略分别解决不同对象：数据并行复制模型，ZeRO/FSDP 分片状态，张量并行拆单层，流水线并行拆层，激活检查点用重复计算换较少存储。</p><p>“权重能加载”只证明推理主体可放下，不证明反向传播能运行。内存估算还会受实现、碎片和通信缓冲影响，必须用实测峰值留出安全余量。</p><div class=\"dd-note\"><b>先做内存账：</b>权重、梯度、优化器、激活、通信缓冲和碎片逐项估算，再选并行轴。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>数据并行的语义是同步同一更新<span class=\"dd-badge math\">数据并行</span></h2><p class=\"dd-lead\">每卡看不同样本，为什么最后参数仍保持一致？</p><p>每个 <code>rank</code>（一个参与训练的进程/设备编号）有完整模型副本，计算不同样本的本地梯度；<code>all-reduce</code> 是让所有 rank 共同求和并把结果发回每一方的集合通信。归约后，各 rank 用相同全局平均梯度更新，所以参数保持同步。</p><div class=\"dd-formula\" data-formula-id=\"distributed-training-global-batch-gradient\"><math display=\"block\" aria-label=\"全局批量等于每卡局部批量 b 乘数据并行设备数 n 乘梯度累积步数 a；平均梯度等于各设备梯度之和除以 n\"><mtable><mtr><mtd><msub><mi>B</mi><mtext>全局</mtext></msub><mo>=</mo><mi>b</mi><mo>·</mo><mi>n</mi><mo>·</mo><mi>a</mi></mtd></mtr><mtr><mtd><mover><mi>g</mi><mo>¯</mo></mover><mo>=</mo><mfrac><mn>1</mn><mi>n</mi></mfrac><munderover><mo>∑</mo><mrow><mi>r</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>g</mi><mi>r</mi></msub></mtd></mtr></mtable></math></div><p class=\"dd-formula-note\"><code>B全局</code> 是一次参数更新实际使用的样本数，<code>b</code> 是每卡每个微步的局部 batch，<code>n</code> 是数据并行副本数，<code>a</code> 是累计多少个微步才更新。<code>r</code> 是 rank 编号，<code>gᵣ</code> 是第 r 个 rank 的累计梯度，<code>ḡ</code> 是 all-reduce 后每个副本共同使用的平均梯度。</p><p>扩设备但不调 b/a 会增大全局批量，改变梯度噪声、学习率和训练 token 语义；不能把收敛变化归咎于硬件。梯度归约精度和顺序也影响数值。</p><div class=\"dd-note warn\"><b>loss 看似相同不代表实验相同。</b>　数据顺序、随机流、dropout 和归约非结合性会改变轨迹。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>运行示例：8 卡全局批量与强扩展效率<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">每卡 4 样本、累积 8 步，8 GPU 的一次优化步看了多少样本？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 710 260\" role=\"img\" aria-label=\"八个数据并行 GPU 各做局部微批和梯度累积后通过 all-reduce 同步\"><defs><marker id=\"dt1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><g fill=\"#21252d\" stroke=\"#6b8cbe\"><rect x=\"20\" y=\"45\" width=\"75\" height=\"50\" rx=\"6\"/><rect x=\"105\" y=\"45\" width=\"75\" height=\"50\" rx=\"6\"/><rect x=\"190\" y=\"45\" width=\"75\" height=\"50\" rx=\"6\"/><rect x=\"275\" y=\"45\" width=\"75\" height=\"50\" rx=\"6\"/><rect x=\"360\" y=\"45\" width=\"75\" height=\"50\" rx=\"6\"/><rect x=\"445\" y=\"45\" width=\"75\" height=\"50\" rx=\"6\"/><rect x=\"530\" y=\"45\" width=\"75\" height=\"50\" rx=\"6\"/><rect x=\"615\" y=\"45\" width=\"75\" height=\"50\" rx=\"6\"/></g><g class=\"svg-t\" font-size=\"10\" text-anchor=\"middle\"><text x=\"57\" y=\"75\">GPU0</text><text x=\"142\" y=\"75\">GPU1</text><text x=\"227\" y=\"75\">GPU2</text><text x=\"312\" y=\"75\">GPU3</text><text x=\"397\" y=\"75\">GPU4</text><text x=\"482\" y=\"75\">GPU5</text><text x=\"567\" y=\"75\">GPU6</text><text x=\"652\" y=\"75\">GPU7</text></g><g stroke=\"#6b7484\"><path d=\"M57,95 L310,150\"/><path d=\"M142,95 L325,150\"/><path d=\"M227,95 L340,150\"/><path d=\"M312,95 L350,150\"/><path d=\"M397,95 L360,150\"/><path d=\"M482,95 L375,150\"/><path d=\"M567,95 L390,150\"/><path d=\"M652,95 L405,150\"/></g><rect x=\"275\" y=\"150\" width=\"170\" height=\"62\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"360\" y=\"175\" text-anchor=\"middle\" class=\"svg-t\">梯度 all-reduce</text><text x=\"360\" y=\"197\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">每卡 4×累积8×8卡=256 样本</text></svg><figcaption>图 1　累积期间不必每个 micro-step 通信；第 8 步同步后才进行一次全局更新。</figcaption></figure><p>若单卡处理固定工作耗时 800ms，8 卡同样总工作理想 100ms，实测 140ms，则强扩展效率 <code>800/(8×140)=71.4%</code>。额外 40ms 来自通信、同步和负载不均。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>设备</th><th>同一总工作时间</th><th>加速</th><th>效率</th></tr></thead><tbody><tr><td>1</td><td>800ms</td><td>1×</td><td>100%</td></tr><tr><td>8 理想</td><td>100ms</td><td>8×</td><td>100%</td></tr><tr><td>8 实测</td><td>140ms</td><td>5.71×</td><td>71.4%</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>张量并行拆一层，通信发生在层内<span class=\"dd-badge eng\">张量并行</span></h2><p class=\"dd-lead\">单个 4096×16384 MLP 放不下一张卡，怎样沿行列拆？</p><p>张量并行（TP）把同一层矩阵或注意力头分给多张卡共同计算。列并行把输出列分给设备，输入共享，各卡算局部输出；后续行并行可消费局部特征并用 all-reduce 汇总。<code>collective</code> 是 all-reduce 等多设备共同参与的集合通信；NVLink 是同一服务器内常见的高速 GPU 互连。</p><p>输入是同一批激活和被分片的层权重，输出要经过集合通信拼回与单卡计算语义一致的层结果。TP 降低每卡权重与部分激活，却使小 batch、慢链路和跨节点延迟显著。度数太高时局部矩阵太小，GPU 利用率下降。通信/计算需通过算子融合和异步重叠隐藏。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>轴</th><th>拆什么</th><th>通信频率</th><th>适合</th></tr></thead><tbody><tr><td>数据并行</td><td>样本</td><td>每次梯度同步</td><td>模型单卡可放/状态可分片</td></tr><tr><td>张量并行</td><td>单层矩阵/头</td><td>几乎每层</td><td>单层太大、高速互连</td></tr><tr><td>序列并行</td><td>序列维激活</td><td>与 TP 配合</td><td>长序列激活</td></tr></tbody></table></div><p>每卡内存下降而 tokens/s/GPU 也下降，通常说明通信或局部算子太小抵消了收益；张量并行更适合高速互连域，不应仅为“多用几张卡”跨慢网络扩大。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>流水线并行拆层，气泡由 micro-batch 填充<span class=\"dd-badge math\">流水线</span></h2><p class=\"dd-lead\">4 个阶段、8 个 micro-batch 的理想气泡比例是多少？</p><p>流水线并行把连续模型层分成 p 个阶段；一个大 batch 再拆成 m 个 micro-batch，依次在阶段间前向和反向。“气泡”是某阶段等待数据、没有有效计算的时间。最简单同步 GPipe 调度中，单方向直觉下效率近似 m/(m+p−1)；p=4、m=8 为 8/11≈72.7%，气泡约 27.3%。</p><div class=\"dd-formula\" data-formula-id=\"distributed-training-pipeline-bubble\"><math display=\"block\" aria-label=\"理想流水线气泡比例约等于阶段数 p 减一，除以 micro-batch 数 m 加阶段数 p 减一\"><mrow><msub><mi>f</mi><mtext>气泡</mtext></msub><mo>≈</mo><mfrac><mrow><mi>p</mi><mo>−</mo><mn>1</mn></mrow><mrow><mi>m</mi><mo>+</mo><mi>p</mi><mo>−</mo><mn>1</mn></mrow></mfrac></mrow></math></div><p class=\"dd-formula-note\"><code>f气泡</code> 是理想化空闲时间比例，<code>p</code> 是流水线阶段数，<code>m</code> 是一个批次拆出的 micro-batch 数。式子只描述阶段成本相近的简化调度，不包括通信、前后向差异和交错调度细节。</p><p>增加 m 减气泡但增加激活驻留、调度开销和过小 micro-batch 的内核低效；1F1B 表示稳定阶段交替执行一次前向和一次反向，可降低峰值激活。阶段算力不均时最慢 stage 决定节拍，应按层成本而非层数平均切。</p><div class=\"dd-note warn\"><b>流水线状态有版本。</b>　异步或交错调度可能让不同 micro-batch 使用不同权重版本，需要明确一致性语义。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>ZeRO / FSDP 分片数据并行冗余状态<span class=\"dd-badge eng\">状态分片</span></h2><p class=\"dd-lead\">数据并行每卡都复制 Adam 状态，怎样按 rank 分摊？</p><p>ZeRO 与 FSDP 都让数据并行 rank 不再各自长期保存完整训练状态。ZeRO-1 分片优化器状态，ZeRO-2 再分片梯度，ZeRO-3/FSDP 再分片参数；计算某层前用 <code>all-gather</code> 从各卡收集本层所需参数，反向后用 <code>reduce-scatter</code> 求和梯度并只把不同分片留在各卡。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>阶段</th><th>优化器</th><th>梯度</th><th>参数</th></tr></thead><tbody><tr><td>普通 DP</td><td>复制</td><td>复制</td><td>复制</td></tr><tr><td>ZeRO-1</td><td>分片</td><td>复制</td><td>复制</td></tr><tr><td>ZeRO-2</td><td>分片</td><td>分片</td><td>复制</td></tr><tr><td>ZeRO-3/FSDP</td><td>分片</td><td>分片</td><td>分片/按需聚合</td></tr></tbody></table></div><p>输入是按 rank 分片的参数与状态，输出仍应等价于一次同步数据并行更新。参数 all-gather 的粒度、预取和重计算需匹配网络与层大小；offload 是把部分状态移到 CPU 内存或 NVMe 存储，能容纳更大模型却可能被搬运带宽限制。</p><p>每卡峰值下降而集合通信占比上升，是用通信换内存的预期结果；若恢复检查点或不同 world size 时无法重分片，则部署弹性仍不合格。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>3D 并行是按拓扑组合，而非随意相乘<span class=\"dd-badge eng\">组合</span></h2><p class=\"dd-lead\">64 GPU 怎样分成 DP=8、TP=4、PP=2，通信域如何不同？</p><p>DP、TP、PP 分别表示数据并行、张量并行和流水线并行的度数。总设备 8×4×2=64。TP 组内每层频繁通信，优先放同节点；PP 相邻阶段传激活；DP 组同步梯度或状态，频率相对低但数据量大。专家并行还可能加入 all-to-all，让每个设备同时向多方发送并接收 token。</p><p>rank 映射必须拓扑感知，避免 TP 跨慢网。全局 batch 只由 DP 副本、局部 micro-batch 与累积步数决定，不乘 TP/PP；因为 TP/PP 合作处理同一批样本。</p><div class=\"dd-formula\" data-formula-id=\"distributed-training-3d-global-batch\"><math display=\"block\" aria-label=\"全局批量等于局部微批量乘梯度累积步数乘数据并行度，不乘张量并行度或流水线并行度\"><mrow><msub><mi>B</mi><mtext>全局</mtext></msub><mo>=</mo><msub><mi>B</mi><mtext>微批</mtext></msub><mo>·</mo><mi>a</mi><mo>·</mo><msub><mi>N</mi><mtext>数据并行</mtext></msub><mspace width=\"0.8em\"/><mo>(</mo><mtext>不乘 TP 或 PP</mtext><mo>)</mo></mrow></math></div><p class=\"dd-formula-note\"><code>B微批</code> 是每个数据并行副本一次处理的样本数，<code>a</code> 是梯度累积步数，<code>N数据并行</code> 是处理不同样本的数据副本数。TP 与 PP 只是共同完成同一副本的模型计算，因此不增加本次更新看过的样本。</p><p>输入是设备拓扑、三种并行度和 batch 配置，输出是 rank 分组、通信域与不变的优化器语义。64 GPU 全乘入 batch 会把全局批量算大 8 倍或更多，并错误改变学习率和训练轨迹。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>检查点与故障恢复是规模化的一部分<span class=\"dd-badge eng\">可靠性</span></h2><p class=\"dd-lead\">训练两周后一个节点故障，怎样保证不是从头再来或恢复出错？</p><p>保存模型、优化器、调度器、随机数、数据游标、损失缩放和并行元数据。分片检查点需支持在不同 world size 重分片或明确限制；写入采用临时产物+原子清单，避免一半 rank 成功的损坏快照。</p><p>checkpoint 间隔在写入开销与丢失计算间取舍；大规模故障率随设备数上升。定期执行真实恢复演练，比较恢复后 loss/样本序列，而不只检查文件存在。弹性训练还需处理成员变化的 batch 与随机流。</p><div class=\"dd-note warn\"><b>数据恰好一次语义很难。</b>　恢复可能重复或跳过样本，必须持久化 sampler 状态和全局 step。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>扩展评测要区分强扩展和弱扩展<span class=\"dd-badge intuition\">评测</span></h2><p class=\"dd-lead\">GPU 翻倍，应该保持总问题大小还是每卡问题大小？</p><p>强扩展固定总模型与总工作，测增加设备后同一任务加速多少；弱扩展固定每卡工作，让总问题随设备增加，测单位效率能否保持。输入是不同设备数下的同一实验协议，输出是速度、效率、内存、功耗、恢复与最终质量的联合报告。</p><p><code>tokens/s</code> 是集群每秒处理 token 数，<code>tokens/s/GPU</code> 是每卡效率；MFU 是实际有效模型计算相对硬件理论峰值的比例；collective 占比是集合通信占 step 时间的比例。还应报告数据等待、气泡、重计算、显存峰值、功耗和恢复时间。</p><p>同时验证训练语义：global batch、学习率、token 数、数据顺序、dropout 随机流、loss scaling 与归约精度。吞吐提高但最终质量下降不是成功扩展。MFU 低也只说明硬件未充分用于模型计算，不能单独判断瓶颈来自数据、通信还是小算子。</p><div class=\"dd-note\"><b>瓶颈定位：</b>用 trace 将一个 step 拆成数据读取、前向、反向、集合通信、优化器和检查点，再把时间占比与等待依赖对应起来；GPU 利用率低只是症状。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">分布式训练的核心是数据与状态语义，而不只是设备数量。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>GPU 翻倍速度翻倍</td><td>通信、同步、输入和小矩阵限制效率</td></tr><tr><td>权重放下即可训练</td><td>梯度、优化器、激活和缓冲常更大</td></tr><tr><td>所有 GPU 都乘入全局批量</td><td>只乘数据并行副本，不乘 TP/PP</td></tr><tr><td>ZeRO 只省内存无代价</td><td>按需聚合增加通信与检查点复杂度</td></tr><tr><td>loss 连续即可证明恢复正确</td><td>还需数据游标、随机流和状态一致</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>反向传播、优化器、集合通信与 GPU 内存</td></tr><tr><td><b>本页核心</b></td><td>DP/TP/PP、ZeRO/FSDP、全局批量、拓扑和恢复</td></tr><tr><td>架构</td><td>MoE 专家并行、长上下文、梯度检查点</td></tr><tr><td>规划</td><td>缩放定律、训练数据治理与可观测性</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>核算参数/状态/激活峰值</li><li>选择 DP/TP/PP/分片组合</li><li>按拓扑映射通信域</li><li>固定全局批量与数值语义</li><li>trace 优化计算通信重叠</li><li>真实恢复并以质量/效率联合验收</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>8卡、每卡4、累积8的全局批量？</li><li>8卡实测140ms相对单卡800ms效率？</li><li>TP/PP 为什么不乘入 global batch？</li><li>4阶段8 micro-batch 气泡近似多少？</li><li>ZeRO-3 分片什么？</li><li>假设“分布式训练：沿数据、张量、流水线和状态四个轴拆分”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“分布式训练：沿数据、张量、流水线和状态四个轴拆分”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>4×8×8=256。</li><li>800/(8×140)≈71.4%。</li><li>它们协作处理同一批样本，只有 DP 副本处理不同样本。</li><li>3/(8+3)=27.3%。</li><li>优化器状态、梯度和参数。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1909.08053\" target=\"_blank\" rel=\"noopener\">Megatron-LM</a>：张量模型并行</li><li><a href=\"https://arxiv.org/abs/1910.02054\" target=\"_blank\" rel=\"noopener\">ZeRO</a>：训练状态分片</li><li><a href=\"https://arxiv.org/abs/1811.06965\" target=\"_blank\" rel=\"noopener\">GPipe</a>：流水线并行与 micro-batch</li><li><a href=\"https://pytorch.org/docs/stable/fsdp.html\" target=\"_blank\" rel=\"noopener\">PyTorch FSDP</a>：全分片数据并行实现语义</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
